import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (pos < buf.length && buf[pos] <= 32) pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > 32) pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= 32) pos++;
        boolean neg = buf[pos] == 45;
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > 32) r = r * 10 + (buf[pos++] - 48);
        return neg ? -r : r;
    }

    static int nextInt() { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long k = nextLong();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        // Compress values so the window frequencies fit in an array.
        long[] sorted = a.clone();
        Arrays.sort(sorted);
        int[] id = new int[n], freq = new int[n];
        for (int i = 0; i < n; i++) id[i] = Arrays.binarySearch(sorted, a[i]);
        long total = 0, distinct = 0, best = 0;
        boolean found = false;
        for (int i = 0; i < n; i++) {
            if (freq[id[i]]++ == 0) distinct++;
            total += a[i];
            if (i >= k) {
                if (--freq[id[(int) (i - k)]] == 0) distinct--;
                total -= a[(int) (i - k)];
            }
            if (i >= k - 1 && distinct == k) {
                best = found ? Math.max(best, total) : total;
                found = true;
            }
        }
        System.out.println(found ? best : -1);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	b := next()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	var r int64
	for _, c := range b {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	n, k := int(nextInt()), nextInt()
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	freq := make(map[int64]int)
	var total, distinct, best int64
	found := false
	for i, v := range a {
		if freq[v]++; freq[v] == 1 {
			distinct++
		}
		total += v
		if int64(i) >= k {
			old := a[int64(i)-k]
			if freq[old]--; freq[old] == 0 {
				distinct--
			}
			total -= old
		}
		if int64(i) >= k-1 && distinct == k {
			if !found || total > best {
				best = total
			}
			found = true
		}
	}
	if !found {
		best = -1
	}
	w.WriteString(strconv.FormatInt(best, 10) + "\n")
}
